async function deleteByUserId(
  ctx: { db: any },
  table: string,
  userId: string,
): Promise<number> {
  const rows = await ctx.db
    .query(table)
    .withIndex("by_userId", (q: any) => q.eq("userId", userId))
    .collect();
  for (const r of rows) await ctx.db.delete(r._id);
  return rows.length;
