  const folios = await loadFoliosFromIdb();
  const activeFolioId = await loadActiveFolioIdFromIdb();
  const ids = new Set<string>(folios.map((f) => f.id));
  if (activeFolioId) ids.add(activeFolioId);

  const folioContent: Array<{
    folioId: string;
