419	export const putCitations = internalMutation({
420	  args: {
421	    userId: v.string(),
422	    folioId: v.string(),
423	    entries: v.array(v.any()),
424	  },
425	  returns: v.object({ saved: v.number() }),
426	  handler: async (ctx, { userId, folioId, entries }) => {
427	    if (entries.length > 100) {
428	      throw new Error("At most 100 citations may be saved at once");
429	    }
430	    const row = await ctx.db
431	      .query("bibliographies")
432	      .withIndex("by_userId", (q) => q.eq("userId", userId))
433	      .first();
434	    const merged = [...(row?.entries ?? [])];
435	    for (const raw of entries) {
436	      if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
437	        throw new Error("Each citation must be an object");
438	      }
439	      const entry = { ...raw, folioId } as Record<string, unknown>;
440	      if (typeof entry.title !== "string" || !entry.title.trim()) {
441	        throw new Error("Each citation needs a title");
442	      }
443	      if (typeof entry.id !== "string" || !entry.id.trim()) {
444	        entry.id = crypto.randomUUID();
445	      }
446	      if (typeof entry.accessedAt !== "number") entry.accessedAt = Date.now();
447	      const index = merged.findIndex(
448	        (candidate: { id?: unknown }) => candidate?.id === entry.id,
449	      );
450	      if (index >= 0) merged[index] = { ...merged[index], ...entry };
451	      else merged.push(entry);
452	    }
453	    const now = Date.now();
454	    if (row) await ctx.db.patch(row._id, { entries: merged, updatedAt: now });
455	    else {
456	      await ctx.db.insert("bibliographies", {
457	        userId,
458	        entries: merged,
459	        updatedAt: now,
460	      });
461	    }
462	    return { saved: entries.length };
463	  },
464	});
